//! 대상 앱으로의 키 주입.
//!
//! 대상은 '현재 포커스를 가진 앱'이다. 우리가 대상을 고르지 않는다.
//! 그래서 이 모듈이 성립하려면 floating 창이 포커스를 뺏지 않아야 한다(`window` 참조).

use enigo::{Direction, Enigo, InputError, Key, Keyboard, Settings};

use crate::action::Action;
use crate::profile::UndoMapping;
use crate::shortcut::Shortcut;

/// 주입 실패 원인. 사용자에게 그대로 보여줄 수 있는 문구를 담는다.
#[derive(Debug)]
pub struct EmitError {
    pub message: String,
    /// 권한 문제로 보이는 경우. 화면에서 해결 방법을 함께 안내한다.
    pub needs_permission: bool,
}

impl EmitError {
    /// 키 주입이 아닌 경로(설정 창 열기 등)의 실패를 같은 통로로 흘린다.
    pub fn from_message(message: String) -> Self {
        Self {
            message,
            needs_permission: false,
        }
    }
}

impl std::fmt::Display for EmitError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.message)
    }
}

/// `Enigo`를 상태로 들고 있지 않고 매번 만든다. macOS의 이벤트 소스는 스레드
/// 경계를 넘기기 까다로운 반면, 생성 비용은 주입 예산(100ms)에 비해 무시할 수준이다.
fn keyboard() -> Result<Enigo, EmitError> {
    Enigo::new(&Settings::default()).map_err(|e| EmitError {
        message: format!("키를 보낼 수 없습니다. 손쉬운 사용(접근성) 권한을 확인해 주세요. ({e})"),
        needs_permission: true,
    })
}

fn injected(result: Result<(), InputError>) -> Result<(), EmitError> {
    result.map_err(|e| EmitError {
        message: format!("키 입력을 보내지 못했습니다. ({e})"),
        needs_permission: false,
    })
}

/// 보조키를 누른 채 키 하나를 치고, 반드시 보조키를 놓는다.
///
/// 중간에 실패해도 놓는 것은 건너뛰지 않는다. 보조키가 눌린 채로 남으면
/// 그 뒤의 모든 입력이 조합키가 되어, 사용자는 무엇을 눌러도 엉뚱한 일이
/// 일어나는 상태에 갇힌다.
fn send_shortcut(enigo: &mut Enigo, shortcut: &Shortcut) -> Result<(), InputError> {
    let mut result = Ok(());

    for modifier in &shortcut.modifiers {
        result = result.and_then(|_| enigo.key(modifier.key(), Direction::Press));
    }
    result = result.and_then(|_| enigo.key(shortcut.key, Direction::Click));

    for modifier in shortcut.modifiers.iter().rev() {
        let released = enigo.key(modifier.key(), Direction::Release);
        if result.is_ok() {
            result = released;
        }
    }

    result
}

/// 대상 앱에 동작을 주입한다.
pub fn send(action: Action) -> Result<(), EmitError> {
    let mut enigo = keyboard()?;

    injected(match action {
        Action::Next => enigo.key(Key::Tab, Direction::Click),
        Action::Prev => enigo
            .key(Key::Shift, Direction::Press)
            .and_then(|_| enigo.key(Key::Tab, Direction::Click))
            .and_then(|_| enigo.key(Key::Shift, Direction::Release)),
        Action::Enter => enigo.key(Key::Return, Direction::Click),
        // 설정 창 열기는 키 주입이 아니라 우리 앱 내부 동작이다.
        Action::Settings => Ok(()),
        Action::Shortcut(shortcut) => send_shortcut(&mut enigo, &shortcut),
    })
}

/// 되돌리기.
///
/// 대상 앱이 이 단축키를 지원할 때만 실제로 되돌아간다. 모든 앱에서 되돌릴 수
/// 있다고 사용자에게 약속하지 않는다(PRD F6).
pub fn send_undo(mapping: UndoMapping) -> Result<(), EmitError> {
    let mut enigo = keyboard()?;

    // macOS의 명령 키는 Meta, 그 외 플랫폼의 실행 취소는 Ctrl 조합이다.
    #[cfg(target_os = "macos")]
    let modifier = Key::Meta;
    #[cfg(not(target_os = "macos"))]
    let modifier = Key::Control;

    let result = match mapping {
        UndoMapping::Back => {
            #[cfg(target_os = "macos")]
            {
                enigo
                    .key(Key::Meta, Direction::Press)
                    .and_then(|_| enigo.key(Key::Unicode('['), Direction::Click))
                    .and_then(|_| enigo.key(Key::Meta, Direction::Release))
            }
            #[cfg(not(target_os = "macos"))]
            {
                enigo
                    .key(Key::Alt, Direction::Press)
                    .and_then(|_| enigo.key(Key::LeftArrow, Direction::Click))
                    .and_then(|_| enigo.key(Key::Alt, Direction::Release))
            }
        }
        UndoMapping::Undo => enigo
            .key(modifier, Direction::Press)
            .and_then(|_| enigo.key(Key::Unicode('z'), Direction::Click))
            .and_then(|_| enigo.key(modifier, Direction::Release)),
    };

    injected(result)
}

//! 청각 피드백.
//!
//! 소음이 큰 환경과 저시력 상황 중 어느 하나만 가정하지 않는다(PRD 원칙 4).
//! 화면 강조만으로는 상태 변화를 놓치는 사용자가 있으므로 소리를 함께 낸다.
//!
//! 오디오 장치 핸들은 스레드 경계를 넘길 수 없어서, 전용 스레드가 장치를
//! 소유하고 채널로 신호만 받는다. 장치를 열지 못해도 앱은 그대로 동작한다.

use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::mpsc::{self, Sender};
use std::thread;
use std::time::Duration;

use rodio::Source;
use rodio::source::SineWave;

/// 서로 구분되어야 하는 신호음.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Cue {
    /// 커서가 한 칸 이동했다.
    Tick,
    /// 동작을 실행했다.
    Select,
    /// 되돌리기 창에 들어갔거나 되돌렸다.
    Undo,
    /// 정지했다.
    Pause,
}

impl Cue {
    /// (주파수, 길이, 음량).
    ///
    /// 커서 이동은 초당 한 번꼴로 계속 나므로 짧고 작게 낸다. 되돌리기와 정지는
    /// 사용자가 반드시 알아차려야 하는 상태 변화라 낮고 길게 내 구분한다.
    fn tone(self) -> (f32, u64, f32) {
        match self {
            Cue::Tick => (660.0, 30, 0.06),
            Cue::Select => (940.0, 70, 0.12),
            Cue::Undo => (520.0, 150, 0.12),
            Cue::Pause => (330.0, 180, 0.10),
        }
    }
}

#[derive(Clone)]
pub struct Audio {
    tx: Option<Sender<Cue>>,
    /// 설정에서 끌 수 있다. 스레드는 그대로 두고 신호만 막는다.
    enabled: Arc<AtomicBool>,
}

impl Audio {
    /// 오디오 스레드를 띄운다. `HANBEON_SOUND=off`면 아무것도 하지 않는다.
    pub fn spawn() -> Self {
        if std::env::var("HANBEON_SOUND").is_ok_and(|value| value == "off") {
            return Self {
                tx: None,
                enabled: Arc::new(AtomicBool::new(false)),
            };
        }

        let (tx, rx) = mpsc::channel::<Cue>();

        thread::spawn(move || {
            let sink = match rodio::DeviceSinkBuilder::open_default_sink() {
                Ok(sink) => sink,
                Err(error) => {
                    eprintln!(
                        "소리 장치를 열지 못했습니다. 청각 피드백 없이 동작합니다. ({error})"
                    );
                    return;
                }
            };
            let mixer = sink.mixer();

            while let Ok(cue) = rx.recv() {
                let (hz, ms, amplitude) = cue.tone();
                mixer.add(
                    SineWave::new(hz)
                        .amplify(amplitude)
                        // 갑자기 시작하고 끊기면 딸깍 소리가 섞인다.
                        .fade_in(Duration::from_millis(5))
                        .take_duration(Duration::from_millis(ms)),
                );
            }
        });

        Self {
            tx: Some(tx),
            enabled: Arc::new(AtomicBool::new(true)),
        }
    }

    pub fn set_enabled(&self, enabled: bool) {
        self.enabled.store(enabled, Ordering::Relaxed);
    }

    /// 신호음을 낸다. 재생이 밀리더라도 스캔을 막지 않는다.
    pub fn play(&self, cue: Cue) {
        if !self.enabled.load(Ordering::Relaxed) {
            return;
        }
        if let Some(tx) = &self.tx {
            let _ = tx.send(cue);
        }
    }
}

        Command::Undo => Some(Cue::Undo),
        // 되돌리기 창에 들어간 것도 사용자가 알아야 하는 상태 변화다.
        _ if mode == Mode::Confirm => Some(Cue::Undo),
        _ => Some(Cue::Select),
    }
}

#[derive(Clone)]
pub struct Scanner {
    state: Arc<Mutex<State>>,
    audio: Audio,
    profile: Arc<Mutex<Profile>>,
    journal: Journal,
    led: Option<Arc<LedBridge>>,
}

impl Scanner {
    pub fn new(profile: Arc<Mutex<Profile>>, audio: Audio, journal: Journal) -> Self {
        let state = {
            let profile = profile.lock().expect("프로필 잠금 실패");
            State::new(&profile, Instant::now())
        };

        Self {
            state: Arc::new(Mutex::new(state)),
            audio,
            profile,
            journal,
            led: Some(Arc::new(LedBridge::native_transport())),
        }
    }

    /// 설정이 저장되면 호출한다. 소리 on/off까지 함께 반영한다.
    pub fn apply_profile(&self) {
        let Ok(profile) = self.profile.lock() else {
            return;
        };
        self.audio.set_enabled(profile.sound);
        if let Ok(mut state) = self.state.lock() {
            state.apply_profile(&profile, Instant::now());
        }
    }

    /// 포그라운드 앱에 맞는 칸으로 갈아 끼운다.
    ///
    /// 바뀐 것이 없으면 아무것도 하지 않는다. 이 함수는 300ms마다 불리므로
    /// 매번 상태를 갈아엎으면 커서가 제자리를 맴돌아 스캔이 진행되지 않는다.
    pub fn apply_preset(
        &self,
        app: &AppHandle,
        focused: Option<&FocusedApplication>,
        registry: &Registry,
    ) {
        let enabled = self
            .profile
            .lock()
            .map(|profile| profile.app_buttons)
            .unwrap_or(false);

        let preset = if enabled {
            focused
                .and_then(|focused| registry.lookup(focused))
                .and_then(crate::preset::PresetSelection::from_registry)
        } else {
            None
        };
        let key = preset.as_ref().map(|preset| preset.key.clone());
        let name = preset.as_ref().map(|preset| preset.name.clone());
        let registry_id = preset.as_ref().map(|preset| preset.registry_id.clone());
        let cells = crate::preset::cells_for(preset.as_ref());

        let (snapshot, first_recognition) = {
            let Ok(mut state) = self.state.lock() else {
                return;
            };
            if state.preset_key == key {
                return;
            }
            let first_recognition = registry_id
                .as_ref()
                .is_some_and(|id| state.recognized_registry.insert(id.clone()));
            let now = Instant::now();
            state.apply_cells(cells, key, name.clone(), now);
            (state.snapshot(now), first_recognition)
        };

        let message = preset_message(
            name.as_deref(),
            snapshot.cells.len().saturating_sub(4),
            first_recognition,
        );

        if log_enabled() {
            eprintln!("[preset] {message} (칸 {})", snapshot.cells.len());
        }

        // 칸 수가 달라졌으니 창도 맞춘다. 화면과 실제 칸이 어긋나면 사용자는
        // 보이지 않는 칸을 누르게 된다.
        if let Some(window) = app.get_webview_window("floating") {
            let extras = snapshot
                .cells
                .iter()
                .filter(|cell| cell.kind == Kind::Extra)
                .count();
            let _ = window::fit_cells(&window, extras);
        }

        self.journal.record(Event::Preset {
            preset: name.clone(),
            cells: snapshot.cells.len(),
        });

        // 바뀌었다는 사실을 두 감각으로 알린다(PRD 원칙 4).
        self.audio.play(Cue::Select);
        let _ = app.emit(EVENT_STATE, snapshot);
        let _ = app.emit(EVENT_PRESET, PresetPayload { message });
    }

    pub fn snapshot(&self) -> Option<Snapshot> {
        let now = Instant::now();
        self.state.lock().ok().map(|state| state.snapshot(now))
    }

    /// 상태 확인 루프를 띄운다.
    ///
    /// 모드마다 마감이 다르므로 고정 간격으로 자는 대신 짧은 주기로 마감을
    /// 확인한다. 입력으로 마감이 바뀌어도 한 틱 안에 반영된다.
    pub fn start(&self, app: AppHandle) {
        let state = Arc::clone(&self.state);
        let audio = self.audio.clone();
        let journal = self.journal.clone();
        let led = self.led.as_ref().map(|bridge| bridge.for_worker());

        if let (Some(led), Some(snapshot)) = (&led, self.snapshot()) {
            led.sync(&snapshot);
        }

        thread::spawn(move || {
            loop {
                thread::sleep(TICK);

                let changed = {
                    let Ok(mut state) = state.lock() else {
                        return;
                    };
                    state.advance(Instant::now())
                };

                if let Some(snapshot) = changed {
                    if let Some(led) = &led {
                        led.sync(&snapshot);
                    }
                    // 커서가 움직였을 때만 틱을 낸다. 되돌리기 창이 만료돼
                    // 머무름으로 내려가는 것은 화면 변화로 충분하다.
                    if snapshot.mode == Mode::Scanning {
                        audio.play(Cue::Tick);
                    }

                    journal.record(Event::Cursor {
                        cursor: snapshot.cursor,
                        cell: snapshot
                            .cells
                            .get(snapshot.cursor)
                            .map(|cell| cell.label.clone())
                            .unwrap_or_default(),
                        mode: snapshot.mode.as_str(),
                        interval_ms: snapshot.interval_ms,
                    });

                    let _ = app.emit(EVENT_STATE, snapshot);
                }
            }
        });
    }

    /// 판정된 제스처를 상태기계에 넣는다.
    pub fn handle(&self, app: &AppHandle, judgement: Judgement) {
        let Judgement { gesture, held } = judgement;

        let (outcome, snapshot) = {
            let Ok(mut state) = self.state.lock() else {
                return;
            };
            let now = Instant::now();
            let outcome = match gesture {
                Gesture::Short => state.select(now),
                Gesture::Long => {
                    state.toggle_pause(now);
                    Outcome::default()
                }
            };
            (outcome, state.snapshot(now))
        };

        if log_enabled() {
            eprintln!(
                "[scan] {gesture:?} -> {:?} (mode={:?}, cursor={}, interval={}ms)",
                outcome.command, snapshot.mode, snapshot.cursor, snapshot.interval_ms
            );
        }

        // 스냅샷은 곧 프론트로 넘어가며 소유권을 잃는다. 기록에 쓸 값은
        // 그 전에 챙겨 둔다.
        let mode = snapshot.mode;

        // 화면과 소리를 먼저 바꾸고 키를 보낸다. 주입이 늦어져도 사용자는
        // 자기 입력이 받아들여졌다는 것을 즉시 알 수 있어야 한다.
        if let Some(cue) = cue_for(gesture, outcome.command.as_ref(), snapshot.mode) {
            self.audio.play(cue);
        }
        if let Some(led) = &self.led {
            led.sync(&snapshot);
        }
        let _ = app.emit(EVENT_STATE, snapshot);

        if let Some(adjustment) = outcome.adjustment {
            self.announce(app, adjustment);
        }

        if gesture == Gesture::Long {
            self.journal.record(Event::Pause {
                paused: mode == Mode::Paused,
            });
        }

        self.journal.record(Event::Input {
            gesture: match gesture {
                Gesture::Short => "short",
                Gesture::Long => "long",
            },
            held_ms: held.as_millis() as u64,
        });

        if let Some(command) = outcome.command {
            let mapping = self
                .profile
                .lock()
                .map(|profile| profile.undo_mapping)
                .unwrap_or_default();

            let undo = command == Command::Undo;
            let name = command_name(&command);
            let failure = execute(app, command, mapping);

            self.journal.record(if undo {
                Event::Undo {
                    mapping: format!("{mapping:?}").to_lowercase(),
                    ok: failure.is_none(),
                }
            } else {
                Event::Action {
                    cell: outcome.cell,
                    action: name,
                    reaction_ms: outcome.reaction_ms,
                    steps: outcome.steps,
                    cycle: outcome.cycle,
                    ok: failure.is_none(),
                    error: failure,
                }
            });
        }
    }

    /// 간격이 왜 바뀌었는지 알린다.
    ///
    /// 이유를 알 수 없는 변화는 사용자의 통제감을 무너뜨린다(PRD 원칙 2).
    /// 조정된 값은 프로필에도 반영해 다음 실행으로 이어진다.
    fn announce(&self, app: &AppHandle, adjustment: Adjustment) {
        let description = adjustment
            .reason
            .describe(adjustment.from_ms, adjustment.to_ms);

        if let Ok(mut profile) = self.profile.lock() {
            profile.interval_ms = adjustment.to_ms;
            // 바로 적어 둔다. 종료 시에만 저장하면 강제 종료·정전에서
            // 사용자가 익숙해진 속도를 잃는다. 조정은 자주 일어나지 않고
            // 파일도 작아서 그때마다 쓰는 편이 안전하다.
            if let Err(message) = profile.save(app) {
                eprintln!("조정된 속도를 저장하지 못했습니다. {message}");
            }
        }

        if log_enabled() {
            eprintln!("[scan] 간격 조정: {description}");
        }

        self.journal.record(Event::Interval {
            from_ms: adjustment.from_ms,
            to_ms: adjustment.to_ms,
            reason: description.clone(),
        });

        let _ = app.emit(
            EVENT_INTERVAL,
            IntervalPayload {
                from_ms: adjustment.from_ms,
                to_ms: adjustment.to_ms,
                reason: description,
            },
        );
    }
}

fn preset_message(name: Option<&str>, extras: usize, first_recognition: bool) -> String {
    match name {
        Some(name) if first_recognition => {
            format!("{name} 프로필 인식 완료 · 버튼 {extras}개 추가")
        }
        Some(name) => format!("{name} — 버튼 {extras}개 추가"),
        None => "앱별 버튼 없음".to_string(),
    }
}

/// `HANBEON_LOG=1`이면 상태 전이와 실행 결과를 stderr로 찍는다.
///
/// 정량 검증(PRD 10절)에는 어차피 이벤트 기록이 필요하다. 지금은 진단용
/// 최소 형태이고, M4에서 파일 로그로 확장한다.
fn log_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var("HANBEON_LOG").is_ok())
}

/// 검증할 때 타이밍을 넉넉히 잡기 위한 개발용 통로.
/// 저장된 프로필을 건드리지 않고 시작 간격만 바꿔 끼운다.
pub fn interval_override() -> Option<u64> {
    std::env::var("HANBEON_INTERVAL_MS")
        .ok()
        .and_then(|value| value.parse::<u64>().ok())
}

/// 기록에 남길 동작 이름.
fn command_name(command: &Command) -> String {
    match command {
        Command::Emit(Action::Next) => "next".into(),
        Command::Emit(Action::Prev) => "prev".into(),
        Command::Emit(Action::Enter) => "enter".into(),
        Command::Emit(Action::Settings) | Command::OpenSettings => "settings".into(),
        Command::Emit(Action::Shortcut(shortcut)) => format!("shortcut:{:?}", shortcut.key),
        Command::Undo => "undo".into(),
    }
}

/// 실행하고, 실패했으면 그 사유를 돌려준다.
fn execute(app: &AppHandle, command: Command, mapping: UndoMapping) -> Option<String> {
    let result = match command {
        Command::Emit(action) => emit::send(action),
        Command::Undo => emit::send_undo(mapping),
        Command::OpenSettings => window::show_settings(app).map_err(emit::EmitError::from_message),
    };

    match result {
        Ok(()) => None,
        Err(error) => {
            if log_enabled() {
                eprintln!("[scan] 실행 실패: {}", error.message);
            }
            let message = error.message.clone();
            let _ = app.emit(
                EVENT_ERROR,
                ErrorPayload {
                    message: error.message,
                    needs_permission: error.needs_permission,
                },
            );
            Some(message)
        }
    }
}

