//! 화면에 그려지는 칸과, 커서가 도는 순서.
//!
//! **칸과 순서는 같지 않다.** `Enter`는 칸이 하나지만 순환에는 두 번 나온다.
//! 이동(`>`, `<`) 다음에 가장 자주 하는 일이 선택이기 때문이다. 이동 칸마다
//! 그 뒤에 `Enter`를 끼워 두면, 어느 쪽으로 옮겼든 한 틱만 기다리면 고를 수 있다.
//!
//! 값은 순환에 한 자리를 더 쓰는 것이다. 기본 4칸이 5자리가 되어 최악 대기가
//! 3틱에서 4틱으로 는다. 실제로 가장 자주 밟는 길(이동 → 선택)이 1틱으로
//! 짧아지므로, 자주 하는 일을 싸게 만들고 드문 일을 비싸게 만드는 교환이다.

use crate::shortcut::Shortcut;
use serde::Serialize;

/// 한 칸을 눌렀을 때 일어나는 일.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Action {
    /// Tab — 다음 요소로
    Next,
    /// Shift+Tab — 이전 요소로
    Prev,
    /// Enter — 선택
    Enter,
    /// 설정 화면 진입
    Settings,
    /// 앱별 칸이 보내는 키 조합.
    Shortcut(Shortcut),
}

/// 칸의 갈래. 화면 배치와 순환 순서가 모두 여기서 갈린다.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Kind {
    /// 포커스를 옮기는 칸. 왼쪽에 세로로 쌓인다.
    Move,
    /// 선택. 오른쪽에 이동 칸 전체 높이로 붙는다.
    Enter,
    /// 앱별 칸. 구분선 아래에 따로 모인다.
    Extra,
    /// 설정 열기. 가장 드물게 쓰므로 맨 아래.
    Settings,
}

/// 화면에 그려지는 칸 하나.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Cell {
    /// 칸에 크게 적히는 글자.
    pub label: String,
    /// 커서가 왔을 때 아래에 작게 적히는 이름.
    pub name: String,
    pub kind: Kind,
    pub action: Action,
}

impl Cell {
    pub fn new(label: &str, name: &str, kind: Kind, action: Action) -> Self {
        Self {
            label: label.to_string(),
            name: name.to_string(),
            kind,
            action,
        }
    }
}

/// 어떤 앱에서도 바뀌지 않는 기본 칸.
///
/// 앱별 칸은 `설정` 앞에 끼어든다(`preset::cells_for`).
pub fn base_cells() -> Vec<Cell> {
    vec![
        Cell::new(">", "다음으로", Kind::Move, Action::Next),
        Cell::new("<", "이전으로", Kind::Move, Action::Prev),
        Cell::new("Enter", "선택", Kind::Enter, Action::Enter),
        Cell::new("설정", "설정 열기", Kind::Settings, Action::Settings),
    ]
}

/// 커서가 도는 순서. 값은 `cells`의 자리번호다.
///
/// 이동 칸 하나마다 그 뒤에 `Enter`를 끼운다. 그래서 `Enter`는 칸이 하나여도
/// 순환에는 이동 칸 수만큼 나온다.
pub fn scan_order(cells: &[Cell]) -> Vec<usize> {
    let index_of = |kind: Kind| cells.iter().position(|cell| cell.kind == kind);
    let enter = index_of(Kind::Enter);

    let mut order = Vec::new();

    for (index, cell) in cells.iter().enumerate() {
        if cell.kind == Kind::Move {
            order.push(index);
            if let Some(enter) = enter {
                order.push(enter);
            }
        }
    }

    for (index, cell) in cells.iter().enumerate() {
        if cell.kind == Kind::Extra {
            order.push(index);
        }
    }

    for (index, cell) in cells.iter().enumerate() {
        if cell.kind == Kind::Settings {
            order.push(index);
        }
    }

    // 어떤 칸도 갈래에 걸리지 않는 일은 없어야 하지만, 비어 있는 순서를
    // 돌려주면 커서가 나눗셈에서 터진다.
    if order.is_empty() {
        order.push(0);
    }

    order
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn 기본_칸은_이동_둘과_선택과_설정이다() {
        let cells = base_cells();
        assert_eq!(cells.len(), 4);
        assert_eq!(cells[0].action, Action::Next);
        assert_eq!(cells[1].action, Action::Prev);
        assert_eq!(cells[2].kind, Kind::Enter);
        assert_eq!(cells[3].kind, Kind::Settings);
    }

    #[test]
    fn 이동_칸마다_뒤에_선택이_끼어든다() {
        let cells = base_cells();
        let order = scan_order(&cells);

        // > → Enter → < → Enter → 설정
        assert_eq!(order, vec![0, 2, 1, 2, 3]);
    }

    #[test]
    fn 선택은_칸이_하나여도_순환에_두_번_나온다() {
        let cells = base_cells();
        let order = scan_order(&cells);
        let enter = cells.iter().position(|c| c.kind == Kind::Enter).unwrap();

        assert_eq!(order.iter().filter(|&&i| i == enter).count(), 2);
    }

    #[test]
    fn 설정은_언제나_순환의_맨_끝이다() {
        let mut cells = base_cells();
        cells.insert(
            3,
            Cell::new("다음 장", "페이지 넘기기", Kind::Extra, Action::Next),
        );

        let order = scan_order(&cells);
        let last = *order.last().unwrap();
        assert_eq!(cells[last].kind, Kind::Settings);
    }

    #[test]
    fn 앱별_칸은_설정_앞에_들어간다() {
        let mut cells = base_cells();
        cells.insert(
            3,
            Cell::new("다음 장", "페이지 넘기기", Kind::Extra, Action::Next),
        );

        let order = scan_order(&cells);
        // > Enter < Enter 다음장 설정
        assert_eq!(order.len(), 6);
        assert_eq!(cells[order[4]].kind, Kind::Extra);
        assert_eq!(cells[order[5]].kind, Kind::Settings);
    }
}

//! 플랫폼에 매이지 않은 키 표현.
//!
//! 프리셋이 적는 키(`shortcut`)와 실제로 그 키를 보내는 쪽(`emit`)을 갈라 놓는다.
//! 갈라 놓는 이유는 보내는 방법이 플랫폼마다 완전히 다르기 때문이다. 데스크톱은
//! OS에 키 이벤트를 주입하지만, 안드로이드는 그게 아예 막혀 있어서 접근성
//! 서비스로 노드를 옮기거나 시스템 동작을 호출해야 한다.
//!
//! 그래서 여기에는 '무엇을 하려는가'만 적고 '어떻게 보내는가'는 적지 않는다.
//! enigo 타입을 이 안에 들이면 코어가 데스크톱 전용이 되어 버린다.

use serde::Serialize;

/// 앱별 칸이 보낼 수 있는 키.
///
/// 목록을 늘릴 때는 그 키가 어떤 플랫폼에서 무엇으로 대응되는지 확인하고 늘린다.
/// 한쪽에서만 되는 키를 넣으면 다른 플랫폼에서 칸이 조용히 사라진다.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Key {
    PageDown,
    PageUp,
    Home,
    End,
    Up,
    Down,
    Left,
    Right,
    Space,
    Enter,
    Tab,
    Escape,
    /// 미디어 키는 앱이 아니라 시스템이 처리한다. 그래서 어떤 앱이 앞에 있든
    /// 같은 키로 동작하고, 안드로이드에도 같은 개념이 그대로 있다.
    MediaPlayPause,
    MediaNextTrack,
    MediaPrevTrack,
    VolumeUp,
    VolumeDown,
    VolumeMute,
    /// 글자 하나(`cmd+o`의 `o`).
    Char(char),
}

/// 함께 누르는 보조키.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Modifier {
    /// macOS의 명령 키.
    Meta,
    Control,
    Alt,
    Shift,
}

//! 실증용 이벤트 기록.
//!
//! PRD 10절의 정량 지표는 실측으로만 주장할 수 있는데, 지금까지는 잴 수단이
//! 없었다. 무엇이 언제 일어났는지를 파일로 남겨야 성공률·오선택·되돌리기를
//! 나중에 셀 수 있다.
//!
//! **쓰기는 별도 스레드에서 한다.** 커서 이동은 주사 간격마다 일어나는데,
//! 그 자리에서 파일에 쓰면 디스크가 느릴 때 주사 간격이 흔들린다. 간격 오차
//! 예산은 ±30ms뿐이다(PRD 9절).
//!
//! **기록은 이 기기 밖으로 나가지 않는다.** 실증 참여자의 동의 없이 외부로
//! 전송하지 않는다는 것이 PRD 10절의 약속이고, 그래서 네트워크 코드를 두지
//! 않는다.

use std::fs::{self, File, OpenOptions};
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};
use std::sync::mpsc::{self, Sender};
use std::thread;

use chrono::{DateTime, Local};
use serde::Serialize;
use serde_json::json;

/// 한 줄에 하나씩 남기는 사건.
///
/// 값은 모두 문자열·숫자로만 둔다. 코어의 타입을 그대로 넣으면 타입이 바뀔
/// 때마다 지난 기록을 읽을 수 없게 된다.
#[derive(Clone, Debug, Serialize)]
// `rename_all`은 변형 이름에만 걸린다. 항목 이름까지 camelCase로 맞추려면
// `rename_all_fields`가 따로 필요하다.
#[serde(
    tag = "event",
    rename_all = "camelCase",
    rename_all_fields = "camelCase"
)]
pub enum Event {
    /// 앱이 뜨고 졌다.
    Session {
        phase: &'static str,
        version: String,
    },
    /// 스위치 키를 잡았거나 놓쳤다.
    Switch { state: &'static str, key: String },
    /// 커서가 다른 칸으로 옮겨 갔다.
    Cursor {
        cursor: usize,
        cell: String,
        mode: &'static str,
        interval_ms: u64,
    },
    /// 스위치 눌림을 짧게/길게로 판정했다.
    Input { gesture: &'static str, held_ms: u64 },
    /// 칸의 동작을 실행했다.
    ///
    /// `reaction_ms`는 커서가 그 칸에 들어온 뒤 누르기까지 걸린 시간이고,
    /// `steps`는 지난 선택 이후 커서가 지나온 자리 수다. 한 바퀴를 넘겼다면
    /// 원하는 칸을 지나쳐 다시 기다린 것이다.
    Action {
        cell: String,
        action: String,
        /// 커서가 칸에 들어온 뒤 누르기까지. 순환 중에 고른 경우에만 값이 있다.
        ///
        /// 머무름 연타에는 '커서 진입'이 없어서 이 값이 정의되지 않는다(PRD F5).
        /// 0을 적으면 반응이 즉각적이었던 것으로, 누적값을 적으면 한없이 느렸던
        /// 것으로 읽힌다. 둘 다 사실이 아니므로 비운다.
        reaction_ms: Option<u64>,
        /// 누를 때의 모드. 순환 중 선택과 머무름 연타를 갈라 세기 위한 것이다.
        mode: &'static str,
        steps: u32,
        /// 그때 순환에 있던 자리 수. `steps`가 이 값 이상이면 원하는 칸을
        /// 지나쳐 한 바퀴를 더 기다린 것이다. 자리 수는 앱에 따라 달라지므로
        /// 함께 남기지 않으면 나중에 셀 수 없다.
        cycle: usize,
        ok: bool,
        error: Option<String>,
    },
    /// 길게 눌러 정지하거나 풀었다.
    ///
    /// 이게 없으면 정지 구간이 그냥 '기록이 끊긴 자리'로 보인다. 분석할 때
    /// 멈춘 것과 앱이 죽은 것과 자리를 비운 것을 가릴 수 없다.
    Pause { paused: bool },
    /// 되돌리기를 실행했다.
    Undo { mapping: String, ok: bool },
    /// 적응 로직이 주사 간격을 바꿨다.
    Interval {
        from_ms: u64,
        to_ms: u64,
        reason: String,
    },
    /// 앱이 바뀌어 스캔 대상이 달라졌다.
    Preset {
        preset: Option<String>,
        cells: usize,
    },
}

/// 기록을 받아 파일에 적는 통로.
///
/// 꺼져 있거나 파일을 열지 못하면 아무 일도 하지 않는다. 기록을 남기지
/// 못한다고 해서 앱이 멈추면 사용자는 조작 수단을 잃는다.
#[derive(Clone)]
pub struct Journal {
    tx: Option<Sender<Event>>,
}

impl Journal {
    /// 아무것도 적지 않는 기록기.
    pub fn off() -> Self {
        Self { tx: None }
    }

    /// 로그 폴더에 오늘 날짜 파일을 열고 쓰기 스레드를 띄운다.
    pub fn open(log_dir: &Path) -> Self {
        let Some(path) = today_path(log_dir) else {
            eprintln!("기록 폴더를 찾지 못해 이벤트를 남기지 않습니다.");
            return Self::off();
        };

        let file = match OpenOptions::new().create(true).append(true).open(&path) {
            Ok(file) => file,
            Err(error) => {
                eprintln!("기록 파일을 열지 못해 이벤트를 남기지 않습니다. ({error})");
                return Self::off();
            }
        };

        let (tx, rx) = mpsc::channel::<Event>();

        thread::spawn(move || {
            let mut writer = BufWriter::new(file);

            for event in rx {
                if let Err(error) = write_line(&mut writer, &event) {
                    eprintln!("이벤트를 남기지 못했습니다. ({error})");
                    break;
                }
            }

            // 채널이 닫히면 앱이 끝난 것이다. 남은 것을 마저 적는다.
            let _ = writer.flush();
        });

        Self { tx: Some(tx) }
    }

    /// 사건 하나를 남긴다. 실패해도 조용히 넘어간다.
    pub fn record(&self, event: Event) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(event);
        }
    }
}

/// 한 줄에 하나씩, 앞에 시각을 붙여 적는다(JSON Lines).
///
/// 줄마다 독립이라 도중에 앱이 죽어도 그때까지 적힌 것은 읽을 수 있다.
fn write_line(writer: &mut BufWriter<File>, event: &Event) -> std::io::Result<()> {
    let now: DateTime<Local> = Local::now();

    let mut line = json!({
        "at": now.to_rfc3339(),
        "ms": now.timestamp_millis(),
    });

    // 사건의 항목을 시각 옆에 펼쳐 둔다. 분석할 때 중첩을 한 겹 벗기지
    // 않아도 되도록.
    if let (Some(base), Ok(serde_json::Value::Object(fields))) =
        (line.as_object_mut(), serde_json::to_value(event))
    {
        base.extend(fields);
    }

    writeln!(writer, "{line}")?;

    // 줄마다 흘려보낸다. 실증 중에 앱이 강제로 꺼져도 마지막 몇 초를 잃지
    // 않아야 한다 — 그 구간이 대개 가장 알고 싶은 부분이다.
    writer.flush()
}

/// 오늘 날짜의 기록 파일 경로. 폴더가 없으면 만든다.
fn today_path(dir: &Path) -> Option<PathBuf> {
    fs::create_dir_all(dir).ok()?;

    let name = format!("events-{}.jsonl", Local::now().format("%Y-%m-%d"));
    Some(dir.join(name))
}

