    pid: String,
    confidence: UsbConfidence,
    #[serde(default)]
    manufacturer_aliases: Vec<String>,
    #[serde(default)]
    product_aliases: Vec<String>,
}

#[derive(Clone, Copy, Debug, Deserialize)]
#[serde(rename_all = "lowercase")]
enum UsbConfidence {
