            entry,
            &FocusedApplication::linux(None, None, vec!["Evince".into()])
        ));
    }

    #[test]
    fn platform_identifiers_are_not_display_string_normalized() {
        let index = parse_index(index_json("apps/pdf-viewer.json").as_bytes()).unwrap();
        let entry = &index.apps[0];

        assert!(!matches_application(
            entry,
            &FocusedApplication::macos(1, Some("COM.APPLE.PREVIEW".into()))
        ));
        assert!(!matches_application(
            entry,
            &FocusedApplication::linux(None, None, vec!["e-v_i nce".into()])
        ));
    }

    #[test]
    fn rejects_an_unsafe_profile_path() {
        let error = parse_index(index_json("apps/../boards/firmware.ino").as_bytes()).unwrap_err();
        assert!(error.contains("path"));
    }

    #[test]
    fn rejects_an_unknown_index_schema_version() {
        let raw = index_json("apps/pdf-viewer.json")
            .replace("\"schemaVersion\": 1", "\"schemaVersion\": 2");
        let error = parse_index(raw.as_bytes()).unwrap_err();
        assert!(error.contains("schemaVersion"));
    }

    #[test]
    fn rejects_a_board_without_the_registry_schema_fields() {
        let raw = index_json("apps/pdf-viewer.json").replace("\"boards\": []", "\"boards\": [{}]");

        assert!(parse_index(raw.as_bytes()).is_err());
    }

    #[test]
    fn rejects_invalid_or_unknown_board_usb_fields() {
        let board = format!(
            r#"{{
                "id": "arduino-uno-r3",
                "name": "Arduino Uno R3",
                "manifest": "boards/arduino-uno-r3.json",
                "sha256": "{PROFILE_HASH}",
                "detect": {{
                    "usb": [{{
                        "vid": "2341",
                        "pid": "00ZZ",
                        "confidence": "exact",
                        "serialHandshake": true
                    }}]
                }}
            }}"#
        );
        let raw = index_json("apps/pdf-viewer.json")
            .replace("\"boards\": []", &format!("\"boards\": [{board}]"));

        assert!(parse_index(raw.as_bytes()).is_err());
    }

    #[test]
    fn accepts_a_complete_board_registry_entry() {
        let board = format!(
            r#"{{
                "id": "arduino-uno-r3",
                "name": "Arduino Uno R3",
                "manifest": "boards/arduino-uno-r3.json",
                "sha256": "{PROFILE_HASH}",
                "detect": {{
                    "usb": [{{
                        "vid": "2341",
                        "pid": "0043",
                        "confidence": "exact",
                        "manufacturerAliases": ["Arduino LLC"],
                        "productAliases": ["Arduino Uno"]
                    }}]
                }}
            }}"#
        );
        let raw = index_json("apps/pdf-viewer.json")
            .replace("\"boards\": []", &format!("\"boards\": [{board}]"));

        let index = parse_index(raw.as_bytes()).unwrap();
        assert_eq!(index.boards.len(), 1);
    }

    #[test]
    fn parses_actions_for_each_platform_in_registry_order() {
        let raw = profile_json(
            r#"{
                "label": "다음 장",
                "name": "페이지 넘기기",
                "shortcut": {
                    "macos": "pagedown",
                    "windows": "pagedown",
                    "linux": "pagedown"
                }
            }, {
                "label": "이전 장",
                "name": "앞 페이지로",
                "shortcut": {
                    "macos": "pageup",
                    "windows": "pageup"
                }
            }"#,
        );
        let profile = parse_profile(raw.as_bytes(), "pdf-viewer").unwrap();

        let windows = profile.actions_for(Platform::Windows);
        assert_eq!(windows.len(), 2);
        assert_eq!(windows[0].label, "다음 장");
        assert_eq!(windows[1].shortcut, "pageup");

        let linux = profile.actions_for(Platform::Linux);
        assert_eq!(linux.len(), 1);
        assert_eq!(linux[0].shortcut, "pagedown");
    }

    #[test]
    fn rejects_a_profile_with_the_wrong_id() {
        let raw = profile_json(
            r#"{
                "label": "다음 장",
                "name": "페이지 넘기기",
                "shortcut": { "macos": "pagedown" }
            }"#,
        );
        let error = parse_profile(raw.as_bytes(), "music-app").unwrap_err();
        assert!(error.contains("id"));
    }

    #[test]
    fn rejects_more_than_three_actions_or_an_unknown_shortcut() {
        let action = r#"{
            "label": "동작",
            "name": "테스트",
            "shortcut": { "macos": "pagedown" }
        }"#;
        let too_many = profile_json(&[action, action, action, action].join(","));
        assert!(parse_profile(too_many.as_bytes(), "pdf-viewer").is_err());

        let unknown = profile_json(
            r#"{
                "label": "동작",
                "name": "테스트",
                "shortcut": { "macos": "shell+command" }
            }"#,
        );
        assert!(parse_profile(unknown.as_bytes(), "pdf-viewer").is_err());
    }

    #[test]
    fn enforces_index_and_profile_size_limits_before_parsing() {
        assert!(parse_index(&vec![b' '; INDEX_LIMIT + 1]).is_err());
        assert!(parse_profile(&vec![b' '; PROFILE_LIMIT + 1], "pdf-viewer").is_err());
    }
}

//! 앱별 칸이 보낼 키 조합.
//!
//! 프리셋은 `"pagedown"`, `"cmd+o"`, `"mediaplaypause"` 같은 문자열로 키를 적는다.
//! 여기서 그것을 실제로 보낼 수 있는 형태로 바꾼다.
//!
//! 해석하지 못한 문자열은 조용히 넘기지 않는다. 없는 칸이 생기면 사용자는
//! 자기가 익힌 자리에서 다른 동작이 나오는 것을 겪게 되고, 그게 왜인지 알
//! 방법이 없다. 프리셋을 만들 때 걸러 내고, 걸러졌다는 사실을 남긴다.

use enigo::Key;
use serde::Serialize;

/// 함께 누르는 보조키.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub enum Modifier {
    /// macOS의 명령 키.
    Meta,
    Control,
    Alt,
    Shift,
}

impl Modifier {
    pub fn key(self) -> Key {
        match self {
            Modifier::Meta => Key::Meta,
            Modifier::Control => Key::Control,
            Modifier::Alt => Key::Alt,
            Modifier::Shift => Key::Shift,
        }
    }

    fn parse(token: &str) -> Option<Self> {
        match token {
            "cmd" | "command" | "meta" | "super" => Some(Modifier::Meta),
            "ctrl" | "control" => Some(Modifier::Control),
            "alt" | "option" => Some(Modifier::Alt),
            "shift" => Some(Modifier::Shift),
            _ => None,
        }
    }
}

/// 보낼 키 하나와, 함께 누를 보조키들.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Shortcut {
    pub modifiers: Vec<Modifier>,
    pub key: Key,
}

/// 보조키 없이 단독으로 쓰는 키 이름.
fn plain_key(token: &str) -> Option<Key> {
    Some(match token {
        "pagedown" | "pgdn" => Key::PageDown,
        "pageup" | "pgup" => Key::PageUp,
        "home" => Key::Home,
        "end" => Key::End,
        "up" => Key::UpArrow,
        "down" => Key::DownArrow,
        "left" => Key::LeftArrow,
        "right" => Key::RightArrow,
        "space" => Key::Space,
        "enter" | "return" => Key::Return,
        "tab" => Key::Tab,
        "escape" | "esc" => Key::Escape,
        // 미디어 키는 앱 전용 단축키가 아니라 시스템이 처리한다. 그래서 어떤
        // 음악 앱이 앞에 있든 같은 키로 동작한다.
        "mediaplaypause" | "playpause" => Key::MediaPlayPause,
        "medianexttrack" | "nexttrack" => Key::MediaNextTrack,
        "mediaprevtrack" | "prevtrack" => Key::MediaPrevTrack,
        "volumeup" => Key::VolumeUp,
        "volumedown" => Key::VolumeDown,
        "volumemute" | "mute" => Key::VolumeMute,
        _ => return None,
    })
}

/// `"cmd+o"`, `"pagedown"` 같은 표기를 해석한다. 해석하지 못하면 `None`.
pub fn parse(spec: &str) -> Option<Shortcut> {
    let spec = spec.trim().to_ascii_lowercase();
    if spec.is_empty() {
        return None;
    }

    let mut tokens: Vec<&str> = spec.split('+').map(str::trim).collect();
    let last = tokens.pop()?;

    let mut modifiers = Vec::new();
    for token in tokens {
        modifiers.push(Modifier::parse(token)?);
    }

    // 마지막 자리는 이름 있는 키이거나, 글자 하나(`cmd+o`의 `o`)다.
    let key = match plain_key(last) {
        Some(key) => key,
        None => {
            let mut chars = last.chars();
            match (chars.next(), chars.next()) {
                (Some(single), None) => Key::Unicode(single),
                _ => return None,
            }
        }
    };

    Some(Shortcut { modifiers, key })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn 이름_있는_키를_해석한다() {
        assert_eq!(
            parse("pagedown"),
            Some(Shortcut {
                modifiers: vec![],
                key: Key::PageDown
            })
        );
    }

    #[test]
    fn 보조키_조합을_해석한다() {
        assert_eq!(
            parse("cmd+o"),
            Some(Shortcut {
                modifiers: vec![Modifier::Meta],
                key: Key::Unicode('o')
            })
        );
    }

    #[test]
    fn 보조키를_여러_개_받는다() {
        let parsed = parse("cmd+shift+z").expect("해석되어야 한다");
        assert_eq!(parsed.modifiers, vec![Modifier::Meta, Modifier::Shift]);
        assert_eq!(parsed.key, Key::Unicode('z'));
    }

    #[test]
    fn 대소문자와_공백을_가리지_않는다() {
        assert_eq!(parse("  Cmd + O "), parse("cmd+o"));
    }

    #[test]
    fn 미디어_키는_보조키_없이_쓴다() {
        assert_eq!(
            parse("mediaplaypause"),
            Some(Shortcut {
                modifiers: vec![],
                key: Key::MediaPlayPause
            })
        );
    }

    #[test]
    fn 모르는_이름은_해석하지_않는다() {
        // 조용히 아무 키나 보내면 사용자는 익힌 자리에서 다른 동작을 겪는다.
        assert_eq!(parse("페이지다운"), None);
        assert_eq!(parse("cmd+unknownkey"), None);
        assert_eq!(parse(""), None);
    }

    #[test]
    fn 모르는_보조키는_해석하지_않는다() {
        assert_eq!(parse("hyper+o"), None);
    }
}

//! '한번' 데스크톱 코어.
//!
//! 스캔 상태기계·입력 판정·키 주입은 프론트가 아니라 이 코어에 둔다.
//! floating 창이 가려지거나 렌더링이 지연돼도 주사 간격이 흔들리면 안 되고,
//! 스위치 입력 판정(짧게/길게)은 대상 앱으로 키를 보내는 지점과 같은 쪽에
//! 있어야 지연을 예측할 수 있기 때문이다.

mod action;
mod adapt;
mod app_registry;
pub mod arduino;
mod audio;
mod emit;
pub mod focused_application;
mod foreground;
mod input;
mod journal;
mod led;
mod occlusion;
mod preset;
mod profile;
mod scan;
mod shortcut;
mod tray;
mod window;

use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use serde::Serialize;
use tauri::{AppHandle, Emitter, Manager, State};

use audio::Audio;
use input::{GestureDetector, SharedDetector};
use profile::Profile;
use scan::{Scanner, Snapshot};

/// 코어가 들고 있는 현재 프로필. 설정 화면과 적응 로직이 함께 쓴다.
struct SharedProfile(Arc<Mutex<Profile>>);

/// 설정 저장 결과.
///
/// 일부만 실패할 수 있어서 경고를 함께 돌려준다. 스위치 키 등록이 실패했다고
/// 나머지 설정까지 버리면 사용자는 방금 맞춘 속도를 다시 잡아야 한다.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct SaveResult {
    profile: Profile,
    warning: Option<String>,
}

/// 프론트가 창을 띄운 직후 현재 커서를 맞추기 위해 호출한다.
/// 이벤트만으로는 첫 틱이 올 때까지 화면이 비어 있게 된다.
#[tauri::command]
fn scan_snapshot(scanner: State<'_, Scanner>) -> Result<Snapshot, String> {
    scanner
        .snapshot()
        .ok_or_else(|| "스캔 상태를 읽지 못했습니다.".to_string())
}

#[tauri::command]
fn get_profile(shared: State<'_, SharedProfile>) -> Result<Profile, String> {
    shared
        .0
        .lock()
        .map(|profile| profile.clone())
        .map_err(|_| "설정을 읽지 못했습니다.".to_string())
}

#[tauri::command]
fn save_profile(
    app: AppHandle,
    mut next: Profile,
    shared: State<'_, SharedProfile>,
    scanner: State<'_, Scanner>,
    detector: State<'_, SharedDetector>,
) -> Result<SaveResult, String> {
    next.sanitize();

    let previous_key = shared
        .0
        .lock()
        .map(|profile| profile.switch_key.clone())
        .map_err(|_| "설정을 읽지 못했습니다.".to_string())?;

    // 스위치 키가 바뀌면 먼저 붙여본다. 실패하면 키만 되돌리고 나머지는 살린다.
    let mut warning = None;
    if next.switch_key != previous_key {
        let old = input::configured_code(&previous_key);
        let new = input::configured_code(&next.switch_key);
        if let Err(message) = input::rebind(&app, old, new) {
            next.switch_key = previous_key;
            warning = Some(message);
        }
    }

    next.save(&app)?;

    if let Ok(mut profile) = shared.0.lock() {
        *profile = next.clone();
    }
    scanner.apply_profile();
    if let Ok(mut detector) = detector.lock() {
        detector.set_long_press(Duration::from_millis(next.long_press_ms));
    }

    Ok(SaveResult {
        profile: next,
        warning,
    })
}

/// 기록이 어디에 쌓이는지 사용자가 볼 수 있어야 한다. 어디 있는지 모르는
/// 기록은 지울 수도, 실증 담당자에게 건넬 수도 없다.
#[tauri::command]
fn log_directory(app: AppHandle) -> Result<String, String> {
    journal::directory(&app)
        .map(|path| path.display().to_string())
        .ok_or_else(|| "기록 폴더를 찾지 못했습니다.".to_string())
}

#[tauri::command]
fn open_settings(app: AppHandle) -> Result<(), String> {
    window::show_settings(&app)
}

#[tauri::command]
fn close_settings(app: AppHandle) -> Result<(), String> {
    window::hide_settings(&app)
}

pub fn run() {
    let app = tauri::Builder::default()
        .setup(|app| {
            // 앱을 보조 도구로 낮춘다. Dock/전환기에 뜨지 않고,
            // 활성 앱을 가로채지 않아 키 주입 대상이 유지된다.
            #[cfg(target_os = "macos")]
            app.set_activation_policy(tauri::ActivationPolicy::Accessory);

            tray::setup(app)?;

            let mut profile = Profile::load(app.handle());
            // 검증용 통로. 저장된 설정을 건드리지 않고 시작 간격만 바꿔 끼운다.
            if let Some(interval_ms) = scan::interval_override() {
                profile.interval_ms = interval_ms;
                profile.max_interval_ms = profile.max_interval_ms.max(interval_ms);
                profile.sanitize();
            }

            // 창 배치는 프로필을 읽은 다음이어야 한다. 사용자가 옮겨 둔 위치를
            // 모른 채 먼저 띄우면 기본 위치에서 한 번 튄 뒤에 제자리를 찾는다.
            if let Some(floating) = app.get_webview_window("floating") {
                window::prepare_floating(&floating, profile.window_position)?;
            }

            if std::env::var("HANBEON_LOG").is_ok() {
                eprintln!(
                    "[profile] 간격 {}ms (범위 {}~{}ms), 적응 {}, 수동고정 {}, 길게누름 {}ms, 소리 {}, 초기설정 {}",
                    profile.interval_ms,
                    profile.min_interval_ms,
                    profile.max_interval_ms,
                    profile.adaptive,
                    profile.manual_lock,
                    profile.long_press_ms,
                    profile.sound,
                    profile.onboarded,
                );
            }

            let audio = Audio::spawn();
            audio.set_enabled(profile.sound);

            // 실증 지표는 실측으로만 주장할 수 있고, 그러려면 무엇이 언제
            // 일어났는지가 파일로 남아야 한다(PRD 10절).
            let journal = if profile.logging {
                journal::Journal::open(app.handle())
            } else {
                journal::Journal::off()
            };
            journal.record(journal::Event::Session {
                phase: "start",
                version: app.package_info().version.to_string(),
            });

            let switch_code = input::configured_code(&profile.switch_key);
            let detector: SharedDetector = Arc::new(Mutex::new(GestureDetector::new(
                Duration::from_millis(profile.long_press_ms),
            )));

            let profile = Arc::new(Mutex::new(profile));
            let scanner = Scanner::new(Arc::clone(&profile), audio, journal.clone());
            let registry = app_registry::Registry::spawn(
                app.path().app_cache_dir()?.join("hana-cloud"),
            );
            let moves = window::MoveWatch::default();

            app.manage(SharedProfile(Arc::clone(&profile)));
            app.manage(Arc::clone(&detector));
            app.manage(scanner.clone());
            app.manage(registry.clone());
            app.manage(moves.clone());

            moves.watch(app.handle().clone(), Arc::clone(&profile));
            foreground::watch(
                app.handle().clone(),
                Arc::clone(&profile),
                scanner.clone(),
                registry,
            );
            scanner.start(app.handle().clone());

            // Native serial starts at app launch. P/R edges share GestureDetector
            // with the HID/F13 fallback below; Accessibility is used only later
            // when Scanner::handle injects into another app.
            let native_app = app.handle().clone();
            let lifecycle_app = app.handle().clone();
            let native_detector = Arc::clone(&detector);
            let native_scanner = scanner.clone();
            let native_switch = arduino::ArduinoSwitch::spawn(
                arduino::ReconnectPolicy::default(),
                move |event| {
                    if std::env::var("HANBEON_LOG").is_ok() {
                        eprintln!("[arduino] lifecycle: {event:?}");
                    }
                    if let Err(error) = lifecycle_app.emit(arduino::EVENT_LIFECYCLE, event) {
                        eprintln!("Arduino lifecycle event를 보내지 못했습니다. {error}");
                    }
                },
                move |event| {
                    arduino::route_switch_event(
                        &native_detector,
                        event,
                        Instant::now(),
                        |judgement| {
                            input::announce(&native_app, judgement);
                            native_scanner.handle(&native_app, judgement);
                        },
                    );
                },
            );
            app.manage(native_switch);

            let registered = input::register(
                app.handle(),
                detector,
                switch_code,
                move |app, judgement| {
                    scanner.handle(app, judgement);
                },
            );
            journal.record(journal::Event::Switch {
                state: if registered.is_ok() {
                    "registered"
                } else {
                    "failed"
                },
                key: format!("{switch_code:?}"),
            });
            registered?;

            app.manage(journal);

            Ok(())
        })
        .on_window_event(|window, event| {
            // 설정 창을 닫아도 앱은 살아 있어야 한다. 창을 파괴하는 대신 숨기고
            // 보조 도구 정책으로 되돌린다. 그러지 않으면 이후 floating 컨트롤러가
            // 대상 앱의 포커스를 계속 뺏는다.
            if let tauri::WindowEvent::CloseRequested { api, .. } = event
                && window.label() == "settings"
            {
                api.prevent_close();
                let _ = window::hide_settings(window.app_handle());
            }

            // 사용자가 끌어 옮긴 위치를 기억한다. 저장과 활성 상태 복구는
            // 이동이 멎은 뒤에 한 번만 일어난다(`MoveWatch`).
            if let tauri::WindowEvent::Moved(position) = event
                && window.label() == "floating"
                && let Some(moves) = window.app_handle().try_state::<window::MoveWatch>()
            {
                moves.note((position.x, position.y));
            }
        })
        .invoke_handler(tauri::generate_handler![
            scan_snapshot,
            get_profile,
            save_profile,
            open_settings,
            close_settings,
            log_directory
        ])
        .build(tauri::generate_context!())
        .expect("한번 앱을 시작하지 못했습니다");

    app.run(|app, event| {
        // 적응으로 조정된 간격은 메모리에만 있다. 종료할 때 한 번 적어 두어야
        // 다음에 켰을 때 사용자가 익숙해진 속도로 시작한다.
        if let tauri::RunEvent::Exit = event
            && let Some(journal) = app.try_state::<journal::Journal>()
        {
            journal.record(journal::Event::Session {
                phase: "stop",
                version: app.package_info().version.to_string(),
            });
        }

        if let tauri::RunEvent::Exit = event
            && let Some(shared) = app.try_state::<SharedProfile>()
            && let Ok(profile) = shared.0.lock()
            && let Err(message) = profile.save(app)
        {
            eprintln!("종료하며 설정을 저장하지 못했습니다. {message}");
        }
    });
}

//! 지금 앞에 있는 앱을 지켜보는 하나의 루프.
//!
//! 두 가지를 이 한 곳에서 본다. 앱이 바뀌면 스캔 대상을 갈아 끼우고(`preset`),
//! 조작할 요소를 우리가 가리면 창을 반투명하게 한다(`occlusion`). 둘 다 같은
//! 값(활성 앱)에서 출발하므로 루프를 나누면 같은 것을 두 번 묻게 된다.

use std::sync::{Arc, Mutex, OnceLock};
use std::thread;
use std::time::Duration;

use serde::Serialize;
use tauri::{AppHandle, Emitter, Manager};

use crate::app_registry::Registry;
use crate::focused_application::{self, FocusedApplication};
use crate::occlusion::{self, MARGIN};
use crate::profile::Profile;
use crate::scan::Scanner;

/// 가림 여부가 바뀔 때만 프론트로 보낸다.
pub const EVENT_COVER: &str = "window://cover";

/// 확인 주기.
///
/// 주사 간격(최소 800ms)보다 짧아 커서가 한 칸 머무는 동안 최소 두 번은 본다.
/// 더 자주 보면 접근성 API 호출이 늘어 대상 앱이 느려진다.
const POLL: Duration = Duration::from_millis(300);

#[derive(Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct CoverPayload {
    covered: bool,
    /// 가릴 때 쓸 불투명도(퍼센트). 프론트가 프로필을 따로 읽지 않아도 되게
    /// 함께 보낸다 — 설정을 바꾸는 즉시 반영되어야 한다.
    percent: u8,
}

fn log_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var("HANBEON_LOG").is_ok())
}

pub fn watch(app: AppHandle, profile: Arc<Mutex<Profile>>, scanner: Scanner, registry: Registry) {
    thread::spawn(move || {
        let mut covered = false;
        let mut source = focused_application::system_source();

        loop {
            thread::sleep(POLL);

            let front = source.current();

            // 우리 자신이 앞에 있는 경우(설정 창을 열었을 때)는 둘 다 건너뛴다.
            // 포커스 요소로 우리 웹뷰가 잡혀 창이 자기 자신을 가린다고 판정되고,
            // 스캔 대상도 설정 창을 여닫을 때마다 두 번씩 바뀐다.
            let ours = is_ours(front.as_ref(), std::process::id() as i32);

            if !ours {
                scanner.apply_preset(&app, front.as_ref(), &registry);
            }

            let (dim, percent) = profile
                .lock()
                .map(|profile| (profile.dim_when_covered, profile.dim_percent))
                .unwrap_or((false, 100));

            let now = if dim && !ours {
                let window = app
                    .get_webview_window("floating")
                    .as_ref()
                    .and_then(occlusion::window_rect);
                let element = front
                    .as_ref()
                    .and_then(FocusedApplication::pid)
                    .and_then(occlusion::focused_element_rect);

                let verdict = match (window, element) {
                    (Some(window), Some(element)) => window.overlaps(&element, MARGIN),
                    // 창이나 요소 위치를 모르면 가리지 않은 것으로 둔다.
                    _ => false,
                };

                if log_enabled() {
                    eprintln!("[cover] 창 {window:?} 요소 {element:?} -> {verdict}");
                }

                verdict
            } else {
                false
            };

            // 매 주기마다 보내지 않는다. 바뀔 때만 보내야 프론트가 같은 값으로
            // 다시 그리지 않고, 로그도 읽을 수 있는 양으로 남는다.
            if now != covered {
                covered = now;
                let _ = app.emit(EVENT_COVER, CoverPayload { covered, percent });
            }
        }
    });
}

fn is_ours(front: Option<&FocusedApplication>, own_pid: i32) -> bool {
    front.and_then(FocusedApplication::pid) == Some(own_pid)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::focused_application::FocusedApplication;

    #[test]
    fn own_focused_application_is_ignored() {
        let front = FocusedApplication::macos(42, Some("devfive.hanbeon".into()));
        assert!(is_ours(Some(&front), 42));
        assert!(!is_ours(Some(&front), 7));
        assert!(!is_ours(None, 42));
    }
}

//! Sends scan-state LED feedback through the native Arduino transport.

use std::sync::Arc;

use crate::arduino::{self, OutputCommand};
use crate::scan::{Mode, Snapshot};

#[derive(Clone)]
pub struct LedBridge {
    enqueue: Arc<dyn Fn(OutputCommand) + Send + Sync>,
}

impl LedBridge {
    pub fn native_transport() -> Self {
        Self {
            enqueue: Arc::new(|command| {
                let _ = arduino::enqueue_output(command);
            }),
        }
    }

    #[cfg(test)]
    fn native(output: std::sync::mpsc::SyncSender<&'static [u8]>) -> Self {
        Self {
            enqueue: Arc::new(move |command| {
                let _ = output.try_send(command.bytes());
            }),
        }
    }

    pub fn sync(&self, snapshot: &Snapshot) {
        (self.enqueue)(command_for(snapshot));
    }

    pub fn for_worker(&self) -> Self {
        self.clone()
    }
}

fn command_for(snapshot: &Snapshot) -> OutputCommand {
    command_for_mode(snapshot.mode)
}

fn command_for_mode(mode: Mode) -> OutputCommand {
    match mode {
        Mode::Scanning => OutputCommand::Flash,
        Mode::Dwelling | Mode::Confirm | Mode::Paused => OutputCommand::Off,
    }
}

