    restart_next: bool,
    preset: Option<String>,
    mode: Mode,
    interval: Duration,
    /// 현재 모드가 끝나는 시각.
    deadline: Instant,
    /// 현재 모드가 시작될 때 잡힌 길이. `deadline`과 짝으로만 움직인다.
    phase: Duration,
    /// 커서가 지금 칸에 들어온 시각. 반응시간을 재는 기준이다.
    entered_at: Instant,
