    steps: u32,
    /// 마지막으로 사용자가 누른 시각. 쉬고 있던 시간을 놓침에서 걸러 내는 데 쓴다.
    last_input_at: Instant,
    adapter: Adapter,
    limits: Limits,
    adaptation_active: bool,
